            Assert.Equal((next.CampaignTrail, next.CampaignStanding, next.OpenCases, next.NextLevel),
                (d.Next.CampaignTrail, d.Next.CampaignStanding, d.Next.OpenCases, d.Next.NextLevel));
            Assert.Equal(before, Hash.State(g));
            var json = Parse(Write(d));
            LegacyFields(d, json);
            Collections(d, json);
            sawMissing |= next.Cases.Any(c => c.kind == "missing");
            sawFound |= next.Cases.Any(c => c.kind == "found-killing");
            if (g.Result == Outcome.Success)
            {
                sawSuccess = true;
                var report = Parse(Report.Json(scenario.Id, g, run.Checks, true));
                SameJson(json, Property(report, "debrief"));
                Assert.Equal(g.Tick, Property(report, "tick").GetInt32());
                Assert.Equal(g.Cash, Property(report, "cash").GetInt64());
                Assert.Equal(g.Trail, Property(report, "trail").GetInt32());
                Assert.Equal(g.Alert, Property(report, "alert").GetInt32());
                Assert.Equal(g.Standing, Property(report, "standing").GetInt32());
                Assert.Equal(Hash.Hex(g.StartHash), Property(report, "startHash").GetString());
                Assert.Equal(Hash.Hex(g.Checkpoints[g.Checkpoints.Count - 1].hash), Property(report, "finalHash").GetString());
            }
            Assert.Equal(before, Hash.State(g));
        }
        Assert.True(sawMissing);
        Assert.True(sawFound);
        Assert.True(sawSuccess);
    }

    [Fact]
    public void SerializerPreservesMultipleEntriesAssociationsOrderAndMultiplicity()
    {
        // Assemble a serialization boundary fixture solely from actual scenario
        // consequences. Repeated entries must remain repeated, not be coalesced.
        var d = Debrief.Of(Scenarios.Run(Repo.Inputs, Scenarios.Find("N47")!).G);
        Assert.NotEmpty(d.Next.Cases);
        Assert.NotEmpty(d.Next.AreaWatch);
        Assert.Contains(d.Next.Cases, c => c.kind == "missing");
        var originalCases = d.Next.Cases.ToArray();
        var originalWatch = d.Next.AreaWatch.ToArray();
        bool addedFound = false;
        foreach (var scenario in Scenarios.All)
        {
            var found = Debrief.Of(Scenarios.Run(Repo.Inputs, scenario).G).Next;
            if (!found.Cases.Any(c => c.kind == "found-killing")) continue;
            d.Next.Cases.AddRange(found.Cases);
            d.Next.AreaWatch.AddRange(found.AreaWatch);
            addedFound = true;
            break;
        }
        Assert.True(addedFound);
        d.Next.Cases.AddRange(originalCases);
        d.Next.AreaWatch.AddRange(originalWatch);
        var cases = d.Next.Cases.ToArray();
        var watch = d.Next.AreaWatch.ToArray();
        var aggregates = (d.Next.CampaignTrail, d.Next.CampaignStanding, d.Next.OpenCases, d.Next.NextLevel);
        var first = Write(d);
        Collections(d, Parse(first));
        LegacyFields(d, Parse(first));
        Assert.Equal(first, Write(d));
        Assert.Equal(cases, d.Next.Cases.ToArray());
        Assert.Equal(watch, d.Next.AreaWatch.ToArray());
        Assert.Equal(aggregates, (d.Next.CampaignTrail, d.Next.CampaignStanding, d.Next.OpenCases, d.Next.NextLevel));
    }

